INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('booking-confirmed','en','Appointment confirmed','Your workshop appointment is confirmed.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('booking-confirmed','ta','முன்பதிவு உறுதி செய்யப்பட்டது','உங்கள் வாகன சேவை முன்பதிவு உறுதி செய்யப்பட்டது.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('booking-rescheduled','en','Appointment rescheduled','Your appointment time has changed. Sign in to view the current booking.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('booking-rescheduled','ta','முன்பதிவு நேரம் மாற்றப்பட்டது','புதிய முன்பதிவு நேரத்தை அறிய உள்நுழையவும்.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('booking-cancelled','en','Appointment cancelled','Your workshop appointment has been cancelled.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('booking-cancelled','ta','முன்பதிவு ரத்து செய்யப்பட்டது','உங்கள் வாகன சேவை முன்பதிவு ரத்து செய்யப்பட்டது.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('appointment-reminder','en','Upcoming workshop appointment','Your workshop appointment is coming up. Sign in to view the confirmed time.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('appointment-reminder','ta','வாகன சேவை நினைவூட்டல்','உங்கள் முன்பதிவு நேரத்தை அறிய உள்நுழையவும்.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('vehicle-checked-in','en','Vehicle checked in','Your vehicle intake has been recorded by the workshop.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('vehicle-checked-in','ta','வாகன வருகை பதிவு','உங்கள் வாகன வருகை பதிவு செய்யப்பட்டது.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('inspection-completed','en','Workshop inspection recorded','Workshop observations have been recorded. These are not a certified safety inspection.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('inspection-completed','ta','பரிசோதனைக் குறிப்புகள் பதிவு','வாகனப் பரிசோதனைக் குறிப்புகள் பதிவு செய்யப்பட்டன. இது பாதுகாப்புச் சான்றிதழ் அல்ல.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('estimate-awaiting-approval','en','Estimate awaiting your approval','Sign in to review the workshop estimate before authorizing repairs.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('estimate-awaiting-approval','ta','செலவு மதிப்பீட்டிற்கு ஒப்புதல் தேவை','பழுது நீக்க அனுமதிக்கும் முன் மதிப்பீட்டைப் பார்க்க உள்நுழையவும்.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('estimate-approved','en','Estimate approved','Your estimate decision has been recorded.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('estimate-approved','ta','மதிப்பீடு ஒப்புதல்','உங்கள் ஒப்புதல் பதிவு செய்யப்பட்டது.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('estimate-reminder','en','Estimate decision reminder','Your estimate is still awaiting a decision. Sign in to review it.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('estimate-reminder','ta','மதிப்பீட்டு ஒப்புதல் நினைவூட்டல்','மதிப்பீட்டைப் பார்த்து முடிவு தெரிவிக்க உள்நுழையவும்.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('repair-progress','en','Workshop progress update','Your service workflow has been updated. Sign in for current details.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('repair-progress','ta','சேவை முன்னேற்றம்','சேவை நிலை புதுப்பிக்கப்பட்டது. விவரங்களை அறிய உள்நுழையவும்.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('repair-completed','en','Repair work completed','Repair work has completed and is awaiting the remaining quality and delivery checks. This is not a collection notice.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('repair-completed','ta','பழுது நீக்க வேலை முடிந்தது','வேலை முடிந்தது. தரச் சரிபார்ப்பு மற்றும் ஒப்படைப்பு நடைமுறைகள் இன்னும் உள்ளன.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('ready-for-collection','en','Vehicle ready for collection','The workshop has marked your vehicle ready for collection.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('ready-for-collection','ta','வாகனத்தைப் பெற்றுக்கொள்ளலாம்','உங்கள் வாகனம் ஒப்படைப்பிற்குத் தயாராக உள்ளது.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('collection-reminder','en','Vehicle collection reminder','Your vehicle is still marked ready for collection. Contact the workshop to arrange pickup.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('collection-reminder','ta','வாகன ஒப்படைப்பு நினைவூட்டல்','வாகனத்தைப் பெற பணிமனையைத் தொடர்புகொள்ளவும்.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('invoice-available','en','Workshop invoice available','An invoice has been issued. Sign in or contact the workshop for authorized access.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('invoice-available','ta','விலைப்பட்டியல் தயார்','விலைப்பட்டியல் வெளியிடப்பட்டது. அணுகுவதற்கு பணிமனையைத் தொடர்புகொள்ளவும்.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('payment-recorded','en','Workshop payment recorded','The workshop has recorded a payment entry. This does not independently confirm bank settlement.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('payment-recorded','ta','கட்டணப் பதிவு','கட்டணப் பதிவு செய்யப்பட்டது. இது வங்கித் தீர்வை உறுதிசெய்யாது.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('service-completed','en','Thank you for your service visit','Your vehicle delivery has been recorded. Keep your workshop records for reference.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('service-completed','ta','சேவை வருகைக்கு நன்றி','வாகன ஒப்படைப்பு பதிவு செய்யப்பட்டது. சேவை ஆவணங்களைப் பாதுகாக்கவும்.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('maintenance-reminder','en','Maintenance follow-up','Contact your workshop to discuss suitable future maintenance; no manufacturer schedule is inferred.',true);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('maintenance-reminder','ta','பராமரிப்பு நினைவூட்டல்','அடுத்த பராமரிப்பு குறித்து பணிமனையுடன் ஆலோசிக்கவும்.',true);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('outstanding-payment-reminder','en','Outstanding payment reminder','Contact the workshop to review your current invoice balance.',false);
INSERT INTO notification_templates(template_key,language,subject,body,optional) VALUES('outstanding-payment-reminder','ta','நிலுவைக் கட்டண நினைவூட்டல்','தற்போதைய நிலுவை குறித்து பணிமனையைத் தொடர்புகொள்ளவும்.',false);
